package com.universe.school.service; import com.universe.global.exception.*; import jakarta.mail.MessagingException; import jakarta.mail.internet.MimeMessage; import lombok.RequiredArgsConstructor; import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.springframework.beans.factory.ObjectProvider; import org.springframework.beans.factory.annotation.Value; import org.springframework.mail.MailException; import org.springframework.mail.javamail.JavaMailSender; import org.springframework.mail.javamail.MimeMessageHelper; import org.springframework.stereotype.Service; @Service @RequiredArgsConstructor public class SchoolMailService {private static final Logger log=LoggerFactory.getLogger(SchoolMailService.class); private final ObjectProvider<JavaMailSender> senderProvider; @Value("${app.mail.from:}") private String defaultFrom; public String send(String to,String code){JavaMailSender sender=senderProvider.getIfAvailable(); if(sender==null||defaultFrom.isBlank()){log.warn("School verification mail is not configured. Using local dev fallback. to={}, code={}", to, code); return code;} try{MimeMessage m=sender.createMimeMessage(); MimeMessageHelper h=new MimeMessageHelper(m,false,"UTF-8");h.setFrom(defaultFrom);h.setTo(to);h.setSubject("UNI:VERSE 학교 이메일 인증");h.setText("학교 이메일 인증코드: "+code+"\n5분 이내에 입력해주세요.");sender.send(m); return null;}catch(MessagingException|MailException e){log.warn("School verification mail send failed. Using local dev fallback. to={}, code={}", to, code, e); return code;}}}
